"""The generated third-party notices must cover the runtime dependencies (F9.6)."""

from __future__ import annotations

import re
import tomllib
from pathlib import Path

from assetboard.branding import APP_NAME

ROOT = Path(__file__).resolve().parents[2]
NOTICES = ROOT / "THIRD_PARTY_LICENSES"
PYPROJECT = ROOT / "pyproject.toml"
# Review gate: a new expression must be considered against AGPL-3.0-or-later before it is
# allowed here. The generated file keeps the upstream wording where metadata has no SPDX value.
ALLOWED = re.compile(
    r"^(MIT|MIT-0|BSD-[23]-Clause|Apache-2\.0(?: OR BSD-3-Clause)?|ISC|ISC License|"
    r"MPL-2\.0|PSF-2\.0|Dual License|OSI Approved :: (BSD|MIT) License)$"
)


def test_notices_cover_every_direct_runtime_dependency() -> None:
    text = NOTICES.read_text(encoding="utf-8").lower()
    project = tomllib.loads(PYPROJECT.read_text(encoding="utf-8"))
    dependencies = project["project"]["dependencies"]
    for dependency in dependencies:
        name = re.split(r"[<>=!~\[ ]", dependency, maxsplit=1)[0]
        assert f"package: {name.lower()}" in text, name


def test_every_notice_has_a_reviewed_license() -> None:
    for line in NOTICES.read_text(encoding="utf-8").splitlines():
        if not line.startswith("License: "):
            continue
        value = line.removeprefix("License: ")
        assert ALLOWED.fullmatch(value), value
        assert "GPL" not in value.upper(), value


def test_notices_are_not_empty_and_reference_the_vendored_assets() -> None:
    text = NOTICES.read_text(encoding="utf-8")
    assert text.startswith(f"{APP_NAME} third-party notices")
    assert "Package: " in text and "License: " in text
    assert "src/assetboard/static/vendor/README.md" in text
    assert "Generated by scripts/generate_third_party_licenses.py" in text
